import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Navbar from './components/Navbar';
import ProfileList from './pages/ProfileList';
import FriendRequests from './components/FriendRequests';
import LandingPage from './pages/LandingPage';
import Login from './pages/Login';
import Register from './pages/Register';
import { getAuthToken } from './api';
import './App.css';

// Protected Route component to handle authentication
const ProtectedRoute = ({ children }) => {
  const isAuthenticated = !!getAuthToken();

  if (!isAuthenticated) {
    return <Navigate to="/login" />;
  }

  return children;
};

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(!!getAuthToken());

  // Check for token on initial load and when it changes
  useEffect(() => {
    const checkAuth = () => {
      setIsAuthenticated(!!getAuthToken());
    };

    // Check auth status when component mounts
    checkAuth();

    // Set up event listener for storage changes (in case of logout in another tab)
    window.addEventListener('storage', checkAuth);

    // Custom event for auth changes within the app
    window.addEventListener('auth-change', checkAuth);

    return () => {
      window.removeEventListener('storage', checkAuth);
      window.removeEventListener('auth-change', checkAuth);
    };
  }, []);

  return (
    <Router>
      <Navbar isAuthenticated={isAuthenticated} />
      <div className="app-container">
        <Routes>
          <Route path="/" element={<LandingPage />} />

          {/* Auth routes */}
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />

          {/* Protected routes */}
          <Route path="/profiles" element={
            <ProtectedRoute>
              <ProfileList />
            </ProtectedRoute>
          } />

          <Route path="/friends" element={
            <ProtectedRoute>
              <FriendRequests />
            </ProtectedRoute>
          } />

          <Route path="/messages" element={
            <ProtectedRoute>
              <div>Messages Coming Soon</div>
            </ProtectedRoute>
          } />

          <Route path="/upload" element={
            <ProtectedRoute>
              <div>Upload Music Coming Soon</div>
            </ProtectedRoute>
          } />

          <Route path="/profile" element={
            <ProtectedRoute>
              <div>Your Profile</div>
            </ProtectedRoute>
          } />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
